void loadSpriteFlyingPalette(void) {
    if (spriteFlying.palette) {
        return;
    }
    const char *error = NULL;
    spriteFlying.palette = playdate->graphics->loadBitmapTable("sprites/sprite-flying", &error);
    if (error) {
        playdate->system->error("Unable to load bitmap table of sprite Flying: %s", error);
    }
}

